# generated by tools/ail2py.py from binary_records_pack_main.ail; edit the .ail until onelang s16
from binary_record_batch import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

def binary_records_pack_kind(text: str) -> int:
    wanted = 0
    position = 0
    negative = False
    digits = False
    for c in text:
        if position == 0 and (c == '+' or c == '-'):
            negative = c == '-'
        else:
            digit = ord(c) - 48
            if digit < 0 or digit > 9:
                raise ValueError
            if wanted > 6553 or (wanted == 6553 and digit > 5):
                raise ValueError
            wanted = wanted * 10 + digit
            digits = True
        position += 1
    if not digits or (negative and wanted != 0):
        raise ValueError
    return wanted

def main() -> int:
    if len(sys.argv) < 4 or (len(sys.argv) - 2) % 2 != 0:
        print('usage: binary_records_pack output-path kind input-path [kind input-path...]', file=sys.stderr)
        return 2
    try:
        output = sys.argv[1]
        batch = BinaryRecordBatch([])
        for position in range(2, len(sys.argv), 2):
            kind = binary_records_pack_kind(sys.argv[position])
            input = sys.argv[position + 1]
            if input == output:
                raise ValueError
            if file_paths_same(input, output):
                raise ValueError
            data = read_bytes(input)
            batch.append(kind, data)
        write_bytes(output, batch.finish())
        return 0
    except ValueError:
        print('invalid kind, binary record payload, or output aliases an input', file=sys.stderr)
        return 2
    except IndexError:
        print('invalid binary record arguments', file=sys.stderr)
        return 2
    except OSError:
        print('binary record file error', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
